import React, {useEffect, useState} from 'react';
import { Box, CircularProgress, LinearProgress, TextField } from '@mui/material';
import StockTable from './stocksTable';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { backend } from '../../models/contants/contants';
import { Toaster } from 'react-hot-toast';
import { IStock } from '../../models/stock/stock';

const Stocks = () => {
  const [searchedVal, setSearchedVal] = useState("");
    const navigate = useNavigate();
    const [showLoading, setShowLoading] = useState<boolean>(false);
    const [stocks, setStocks] = useState<IStock[]>([]);

    const loadStocks = async () => {
        setShowLoading(true);
        await axios({
            url: backend+"stocks?limit=10000",
            method: "Get",
            headers: {
                authorization: "your token comes here",
            }
        })
            // Handle the response from backend here
            .then((res) => {
                const data: IStock[] = res.data;
                setStocks(data);
                setShowLoading(false);
            })
            .catch((err) => {});
    }

    // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
        loadStocks();
         // eslint-disable-next-line react-hooks/exhaustive-deps
    },[] );

    const gotoAlert = async () => {
        navigate('/alert');
    }

    const filteredStocks = stocks.filter(a=> {
      return a.code?.toLocaleLowerCase().indexOf(searchedVal) > -1 ||
       a.name?.toLocaleLowerCase().indexOf(searchedVal) > -1 ||
       a.sector?.toLocaleLowerCase().indexOf(searchedVal) > -1;
     });

    return (
        <div>
           <div className='page-header'>
           <div className="row">
                <div className="col-6 align-items-center">
                  <div><h6 className="mb-0">Stocks</h6></div>
                  <small className='text-secondary'>found {filteredStocks.length} stocks</small>
                </div>
                <div className="col-6 text-end">
                   

               <TextField size='small'
                        onChange={(e) =>{
                          setSearchedVal(e.target.value.toLocaleLowerCase())}
                        }
                       id="outlined-basic" 
                       placeholder='filter stocks'
                       variant="outlined" 
                       label="filter stocks"/>
                </div>
              </div>
           </div>
          
           <div className="table-responsive page-content">
            <StockTable rows={stocks.filter(a=> {
             return a.code?.toLocaleLowerCase().indexOf(searchedVal) > -1 ||
              a.name?.toLocaleLowerCase().indexOf(searchedVal) > -1 ||
              a.sector?.toLocaleLowerCase().indexOf(searchedVal) > -1 ||
              a.isinNumber?.toLocaleLowerCase().indexOf(searchedVal) > -1;
            }
              
            )}/>
            </div>
             <div className='text-center'>
                  { showLoading && <CircularProgress className='spinner'/>}
                </div>
        </div>
    )
}

export default Stocks;
