// services/AlertService.ts
import axios from 'axios';
import { IAlertHistory } from '../../models/alert/alerthistory';
import { backend } from '../../models/contants/contants';
import { IAlert } from '../../models/alert/alert';

  export const loadUserAlertHistory = async (token:any, alertKey:string|null = null): Promise<IAlertHistory[]> => {
    try {
      const response = await axios({
        url: `${backend}alertshistory/${alertKey ?? ''}`,
        method: "GET",
        headers: {
          authorization: `Bearer ${token}`
        }
      });
      return response.data;
    } catch (error) {
      console.error('Error loading user alert history:', error);
      throw error; // Re-throw the error to let the component handle it
    }
  }

  export const loadUserAlerts = async(token:any): Promise<IAlert[]> => {
    try {
      const response = await axios({
        url: `${backend}alerts`,
        method: "GET",
        headers: {
          authorization: `Bearer ${token}`
        }
      });
      return response.data;
    } catch (error) {
      console.error('Error loading user alerts:', error);
      throw error; // Re-throw the error to let the component handle it
    }
  }
