import React, {useEffect, useRef, useState} from 'react';
import toast, { Toaster } from 'react-hot-toast';
import { useNavigate } from 'react-router-dom';
import { isNullEmptyOrWhitespace, validateEmail } from '../../utility/utility';
import { auth } from '../../auth/firebase';
import { GoogleAuthProvider, sendEmailVerification, signInWithEmailAndPassword, signInWithPopup, signInWithRedirect } from 'firebase/auth';
import { GoogleIcon } from '../common/utilitycomp';

const SignIn = () => {

     const [email, setEmail] = useState('');
     const [password, setPassword] = useState('');
     const [rememberMe, setRememberMe] = useState(false);

     const emailInputRef = useRef<HTMLInputElement>(null);
     const passwordInputRef = useRef<HTMLInputElement>(null);
  
    // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
        //loadUserAlerts(0,100);
         // eslint-disable-next-line react-hooks/exhaustive-deps
    },[] );

    const onSignIn = async () => {
      if(validate()){
        signInWithEmailAndPassword(auth, email, password)
        .then((userCredential:any) => {
            // Signed in
            debugger;
            const user = userCredential.user;
            if(user.emailVerified){
              navigate("/");
            }else{
              if(window.confirm('Email is not verified. Would you like to resend verification link?')){
                       sendEmailVerification(user)
                        .then(() => {
                            alert('Please verify the verification link sent to email and proceed to signin.');
                        })
                        .catch((error:any) => {
                          alert(error.message.replace("Firebase: ",""));
                            const errorCode = error.code;
                            const errorMessage = error.message;
                            console.log(errorCode, errorMessage);
                        });
              }
            }
          
            console.log(user);
        })
        .catch((error:any) => {
          alert(error.message.replace("Firebase: ",""));
          //Error (auth/invalid-credential).
            const errorCode = error.code;
            const errorMessage = error.message;
            console.log(errorCode, errorMessage)
        });
      }
    }

    const onSignUpUsingGoogle = async () => {
          const provider = new GoogleAuthProvider();
          // whenever a user interacts with the provider, we force them to select an account
          provider.setCustomParameters({   
              prompt : "select_account "
          });
          
         await signInWithPopup(auth,provider);

          // var res = await  signInWithRedirect(auth, provider);
           //console.log('res');
           navigate("/");
          // console.log(res);
        }

    const validate = () => {
    let isValid = true;
    toast.dismiss();

    if(isNullEmptyOrWhitespace(email)){
      toast.error('Enter email');
      if(isValid)
        emailInputRef.current?.focus();
      isValid = false;
    }else if(!validateEmail(email)){
      if(isValid)
        emailInputRef.current?.focus();
      toast.error('Enter valid email');
      isValid = false;
    }

    if(isNullEmptyOrWhitespace(password)){
      if(isValid)
        passwordInputRef.current?.focus();
      toast.error('Enter password');
      isValid = false;
    }

      return isValid;
  };
  
    const navigate = useNavigate();
    
    return (
        <div>
         <Toaster position="bottom-center" reverseOrder={false}/>
          <div className="mt-100">
        <div className="container">
          <div className="row">
            <div className="col-xl-3 col-lg-4"></div>
            <div className="col-xl-6 col-lg-4">
              <div className="card">
                <div className="card-header">
                  <h4 className="font-weight-bold">Sign In</h4>
                  <p className="mb-0">Enter your email and password to sign in</p>
                </div>
                <div className="card-body">
                  <form role="form">
                  <div className="input-group input-group-outline mb-3">
                      <label className="form-label">Email</label>
                      <input ref={emailInputRef} value={email} onChange={(e) =>{setEmail(e.target.value);}} type="email" className="form-control input-group-lg"/>
                    </div>
                    <div className="input-group input-group-outline mb-3">
                      <label className="form-label">Password</label>
                      <input ref={passwordInputRef} value={password} onChange={(e) =>{setPassword(e.target.value);}} type="password" className="form-control"/>
                    </div>
                    {/* <div className="form-check form-check-info text-start ps-0">
                    <input checked={rememberMe} onChange={(e) => {setRememberMe(e.target.checked)}} type="checkbox" value="" id="flexCheckDefault" />
                     
                      <label className="form-check-label">
                        &nbsp;Remember me
                      </label>
                    </div> */}
                    <div className="text-center">
                      <button onClick={() => onSignIn()} type="button" className="btn btn-lg bg-gradient-light btn-lg w-100 mt-4">
                        Sign in</button>
                      <button onClick={() => onSignUpUsingGoogle()} type="button" className="btn btn-lg bg-gradient-light btn-lg w-100 mb-0">
                     {GoogleIcon}
                      &nbsp; Sign in using Google</button>
                    </div>
                  </form>
                </div>
                <div className="card-footer text-center pt-0 px-lg-2 px-1">
                  <p className="mb-2 text-sm mx-auto">
                  Don't have an account?
                    <a href="#/signup" className="link font-weight-bold">&nbsp;Sign up</a>
                  </p>
                  <a className="link" rel="noreferrer" 
                  href="#/"><i className="material-symbols-rounded text-sm me-2">arrow_back</i>back to home</a>
                 &nbsp; <span className='text-secondary'>|</span>
                   <a href="#/forgotpassword" className="ml-5 link text-danger">forgot password?</a>
                </div>
              </div>
            </div>
            <div className="col-xl-3 col-lg-4"></div>
          </div>
        </div>
      </div>
      </div>
    )
}

export default SignIn;
