import React, {useContext, useEffect, useState} from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { AuthContextType, AuthContext } from '../../auth/authContext';
import { auth } from '../../auth/firebase';
import { isCurrentPath, UserAvatar } from '../common/utilitycomp';
import { TextField } from '@mui/material';
import { updateProfile } from 'firebase/auth';
import toast, { Toaster } from 'react-hot-toast';
import ProfileHead from './profilehead';

const Profile = () => {
    const [isEditMode, setIsEditMode] = useState(false);
    const [userName, setUserName] = useState("");
    const location = useLocation();
    const { pathname } = location;
 const { user, logOut } = useContext<AuthContextType|null>(AuthContext)!;
   const navigate = useNavigate();
    // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
        //loadUserAlerts(0,100);
         // eslint-disable-next-line react-hooks/exhaustive-deps
    },[] );


    const deleteAccount = async () => {
        if(window.confirm('Deleting account is irreversible and all the data will be lost. Would you like to continue?')){
            debugger;
            await auth?.currentUser?.delete().then((res:any)=>{
                alert('account deleted');
                navigate("/");
            }).catch((err:any)=>{
                logOut();
                alert('error occured while deleting account.');
            });
        }
    }

     const updateUserDetails = async () => {
       await updateProfile(auth?.currentUser!,{displayName:userName})
       .then((res:any) =>{
        toast.success('user details updated.');
        setIsEditMode(false);
       }).catch((error:any) =>{
        alert('unable to update user details');
        const errorCode = error.code;
        const errorMessage = error.message;
        console.log(errorCode, errorMessage);
       });
        }
  
    return (
            <div>
                <Toaster position="bottom-center" reverseOrder={false}/>
                <ProfileHead/>
                <div className='content-margin mt-3'>
                    <div className='card col-md-6'>
                        <div className='card-header'>
                           <div className='row'>
                           <div className="col-6 d-flex align-items-center"><h6 className="mb-0">User Details</h6></div>
                           <div className="col-6 text-end">

                           {!isEditMode && 
                      <button onClick={()=>{setUserName(auth?.currentUser?.displayName!); setIsEditMode(true)}} className="btn bg-gradient-light btn-sm mb-0">
                      <svg className='mb-2px' xmlns="http://www.w3.org/2000/svg" height="15px" viewBox="0 -960 960 960" width="15px" fill="#4CAF50"><path d="M200-200h57l391-391-57-57-391 391v57Zm-80 80v-170l528-527q12-11 26.5-17t30.5-6q16 0 31 6t26 18l55 56q12 11 17.5 26t5.5 30q0 16-5.5 30.5T817-647L290-120H120Zm640-584-56-56 56 56Zm-141 85-28-29 57 57-29-28Z"/></svg>
                       &nbsp; Edit</button>}

                       {isEditMode && <>
                      <button onClick={()=>{updateUserDetails()}} className="btn bg-gradient-light btn-sm mb-0">
                      <span className="material-symbols-rounded text-sm  text-success">check</span>&nbsp; Save</button>
                       &nbsp;
                       <button onClick={()=>{setIsEditMode(false)}} className="btn bg-gradient-light btn-sm mb-0">
                       <span className="material-symbols-rounded text-sm  text-danger">close</span>&nbsp; Cancel</button>
                       </>
                       }
                    </div>
                           </div>
                        </div>
                        <div className='card-body'>
                        <ul className="list-group mb-3">
                  <li className="list-group-item border-0 ps-0">
                   {!isEditMode && <><span className="font-weight-bold">Display name:</span> &nbsp; {auth?.currentUser?.displayName}</>}
                  {isEditMode && <TextField 
                                        value={userName} 
                                        onChange={(e) =>{
                                          setUserName(e.target.value);
                                         }
                                       }
                                       id="outlined-basic" label="display name" 
                                       variant="outlined" />}
                    
                    </li>
                  </ul>
                        <button onClick={() => deleteAccount()} className='btn btn-danger'>Delete account</button>
                        </div>
                    </div>
                
                </div>
            </div>
    )
}

export default Profile;
