import React, {useEffect, useState} from 'react';
import axios from 'axios';
import { backend } from '../../models/contants/contants';
import { useParams } from 'react-router-dom';
import { getColor } from '../../utility/utility';
import AnnouncementsComp from '../announcement/announcementComp';
import { IStock } from '../../models/stock/stock';
import { StockAvatar } from '../common/utilitycomp';

const Stock = () => {
  const params= useParams();
  const [stock, setStock] = useState<IStock|undefined>(
    undefined);

    const loadStock = async (stockCode:string) => {
              await axios({
                  url: backend+'stocks/'+stockCode,
                  method: "Get",
                  headers: {
                      authorization: "your token comes here",
                  }
              })
                  .then((res) => {
                      const data: IStock = res.data;
                      setStock(data);
                  })
                  .catch((err) => {
                    //window.alert('unable to get alert details')
                  });
          }
 // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
      if(params && params["stockCode"]){
        loadStock(params["stockCode"]);
      }
       // eslint-disable-next-line react-hooks/exhaustive-deps
    },[]);

    const headerName = stock?.code+"'s Announcements";

    return (
      <div>
       { stock && 
       <>
              <div className='page-header'>
            <ol className="breadcrumb bg-transparent mb-0 pb-0 pt-1 px-0 me-sm-6 me-5">
              <li className="breadcrumb-item"><a className='text-primary' href="#/stocks">
              <svg className="mb-2px" xmlns="http://www.w3.org/2000/svg" height="18px" viewBox="0 -960 960 960" width="18px" fill="#59636e"><path d="M200-120q-33 0-56.5-23.5T120-200v-640h80v640h640v80H200Zm40-120v-360h160v360H240Zm200 0v-560h160v560H440Zm200 0v-200h160v200H640Z"/></svg>
          
              &nbsp; Stock data</a></li>

              <li className="breadcrumb-item text-dark active" aria-current="page"><strong>
                <span>{stock.name}</span></strong></li>
                </ol>
       </div>
       <div className='content-margin'>
        <div className='card mb-3'>
<div className='card-body'>
<ul className="list-group mb-3">
                  <li className="list-group-item border-0 ps-0">
                    <strong className="text-dark">Company:</strong> &nbsp; {stock.name} (#{stock.code})</li>
                    <li className="list-group-item border-0 ps-0">
                    <strong className="text-dark">Sector:</strong> &nbsp; {stock.sector}</li>
                    <li className="list-group-item border-0 ps-0">
                    <strong className="text-dark">Market Cap:</strong> &nbsp; {stock.marketCap } Cr</li>
                 
                    <li className="list-group-item border-0 ps-0">
                      <strong className="text-dark">Exchanges Listed In:</strong> &nbsp; 
                     {stock.isBSEListed } <a className="btn-link text-success text-gradient" target='blank' href={stock.bseURL}>
                      BSE <i className="material-symbols-rounded  me-2 text-sm">open_in_new</i></a>
                      {stock.isNSEListed } <a className="btn-link text-success text-gradient" target='blank' href={stock.bseURL}>
                       NSE <i className="material-symbols-rounded  me-2 text-sm">open_in_new</i></a>
                      </li>
                  </ul>

                  <div className="card bg-primary">
                <div>
                <AnnouncementsComp isCard={true} headerName={headerName} filterbyStock={stock.code}></AnnouncementsComp>
            </div>
      </div>
</div>
        </div>
       </div>
       </>
      }
</div>

)}

export default Stock;
