import React, {useContext, useEffect, useState} from 'react';
import { Box, CircularProgress, LinearProgress } from '@mui/material';
import AlertTable from './alertTable';
import { useNavigate } from 'react-router-dom';
import { IAlert, IAlertTable } from '../../models/alert/alert';
import axios from 'axios';
import { backend } from '../../models/contants/contants';
import { Toaster } from 'react-hot-toast';
import { AuthContextType, AuthContext } from '../../auth/authContext';

const Alerts = () => {
    const navigate = useNavigate();
    const { user, isUserLoggedIn } = useContext<AuthContextType|null>(AuthContext)!;
    const [showLoading, setShowLoading] = useState<boolean>(true);
    const [userAlerts, setUserAlerts] = useState<IAlert[]>([]);

    const loadUserAlerts = async () => {
        //setShowLoading(true);
        await axios({
            // Endpoint to send files
            url: backend+"alerts",
            method: "Get",
            headers: {
                // Add any auth token here
                authorization: 'Bearer '+await user?.getIdToken()
            }
        })
            // Handle the response from backend here
            .then((res) => {
                const data: IAlert[] = res.data;
                setUserAlerts(data);
                setShowLoading(false);
            })
            .catch((err) => {});
    }

    // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
        if(isUserLoggedIn())
        loadUserAlerts();
    else
    setShowLoading(false);
         // eslint-disable-next-line react-hooks/exhaustive-deps
    },[user,showLoading] );

    const gotoAlert = async () => {
        navigate('/alert');
    }
    return (
        <div>
         <Toaster position="bottom-center" reverseOrder={false}/>
         <div className='page-header'>
         <div className="row">
         <div className="col-6 align-items-center">
                  <h6 className="mb-0">Alerts</h6>
                 {!isUserLoggedIn() && <a href='#/signin' className="link text-xs text-warning">! Login to view alerts</a>} 
                </div>
                <div className="col-6 text-end">
                <button onClick={gotoAlert} className="btn btn-sm bg-gradient-secondary mb-0">
                <svg xmlns="http://www.w3.org/2000/svg" height="18px" viewBox="0 -960 960 960" width="18px" fill="#fff"><path d="M440-440H200v-80h240v-240h80v240h240v80H520v240h-80v-240Z"/></svg>
                    &nbsp;&nbsp;Add New Alert</button>
                </div>
         </div>
         </div>
         <div>
            <div className="table-responsive page-content">
              <AlertTable rows={userAlerts}/>
</div>
<div className='text-center'> 
   {!showLoading && userAlerts.length === 0 && <div><img alt='no data' className='avatar-img-sm' src="https://cdn-icons-png.flaticon.com/128/3388/3388419.png"/>
    &nbsp; no records found</div>}
    <div>
{ showLoading && <CircularProgress className='spinner'/>}
</div>
   {isUserLoggedIn() && <a className="url link " href='#/alerthistory'> view alerts history</a>}</div>
         </div>

        </div>
    )
}

export default Alerts;
