import React, {useContext, useEffect, useState} from 'react';
import { CircularProgress, FormControl, InputLabel, MenuItem, Select, ThemeProvider } from '@mui/material';
import { Toaster } from 'react-hot-toast';
import { AuthContextType, AuthContext } from '../../auth/authContext';
import AlertHistoryTable from './alertHistoryTable';
import { IAlertHistory } from '../../models/alert/alerthistory';
import { muiTheme } from '../common/muicomp';
import {loadUserAlertHistory,loadUserAlerts} from '../../services/alert/alertService';
import { IAlert } from '../../models/alert/alert';
import { useParams } from 'react-router-dom';

const AlertHistory = () => {
    const params = useParams();
    const [selectedAlert, setSelectedAlert] = React.useState('all');
    const [userAlerts,setUserAlerts] = useState<IAlert[]>([]);
    const {user, isUserLoggedIn } = useContext<AuthContextType|null>(AuthContext)!;
    const [showLoading,setShowLoading] = useState<boolean>(true);
    const [alertHistoryList, setAlertHistoryList] = useState<IAlertHistory[]>([]);

    const loadPageData = async () => {
        debugger;
      var data =  await loadUserAlerts(await user?.getIdToken());
      setUserAlerts(data);
      if(params["alertKey"])
        setSelectedAlert(params["alertKey"]);
      await loadAlertHistory(params["alertKey"]);
    }

   const  loadAlertHistory = async (alertKey:string|null = null) =>{
    setShowLoading(true);
    var data = await loadUserAlertHistory(await user?.getIdToken(),alertKey !== 'all'? alertKey : null);
    setAlertHistoryList(data);
    setShowLoading(false);
   }
    // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
        if(isUserLoggedIn()){
            loadPageData();
        }
         // eslint-disable-next-line react-hooks/exhaustive-deps
    },[user] );

    const onAlertChange = async (e:any) =>{
        setSelectedAlert(e.target.value);
        loadAlertHistory(e.target.value);
    }
    return (
        <div>
         <Toaster position="bottom-center" reverseOrder={false}/>
         <div className='page-header'>
         <div className="row">
         <div className="col-6 align-items-center">
                  <h6 className="mb-0">Alert History</h6>
                </div>
                <div className="col-6 text-end">

 <ThemeProvider theme={muiTheme}>
                <FormControl style={{width:'auto'}} size="small">
      <InputLabel>select alert</InputLabel>
      <Select 
        value={selectedAlert}
        label="select alert"
        onChange={onAlertChange}
      >
         <MenuItem value="all"> -all-
         </MenuItem>
        {
            userAlerts.map(a => 
                <MenuItem value={a.alertKey}> {a.name}
               </MenuItem>
            )
        }
      </Select>
    </FormControl>
    </ThemeProvider>
      
                {/* <button onClick={gotoAlert} className="btn btn-sm btn-primary mb-0">
                <svg xmlns="http://www.w3.org/2000/svg" height="18px" viewBox="0 -960 960 960" width="18px" fill="#fff"><path d="M440-440H200v-80h240v-240h80v240h240v80H520v240h-80v-240Z"/></svg>
                    &nbsp;&nbsp;Add New Alert</button> */}
                </div>
         </div>
         </div>
         
         <div className="table-responsive page-content">
              <AlertHistoryTable rows={alertHistoryList}/>
            </div>
            <div className='text-center'>
            {showLoading && <CircularProgress className='spinner'/>}
            {!showLoading && alertHistoryList.length === 0 && <div>
            <img alt='no data' className='avatar-img-sm' src="https://cdn-icons-png.flaticon.com/128/3388/3388419.png"/>
            &nbsp; no records found
            </div>}
            </div>
        </div>
    )
}

export default AlertHistory;
